(() => {
  'use strict';
  let csrfToken='', currentWorkspace='', currentRole='', currentUser={name:'',initials:'BS'}, authWorkspaces=[];
  let state={rules:[],reviews:[],audit:[]},currentPage='dashboard',activeFilter='All reviews',activeKnowledge='Guidelines',editCounter=0,apiQueue=Promise.resolve();
  function updateCurrentUser(){document.querySelector('#profile-name').textContent=currentUser.name;document.querySelector('#profile-role').textContent=currentRole;document.querySelector('#profile-initials').textContent=currentUser.initials;document.querySelector('#account-menu').textContent=currentUser.initials}
  function updateWorkspaceUI(){const item=authWorkspaces.find(x=>x.id===currentWorkspace),name=item?.name||'Workspace';document.querySelector('#workspace-name').textContent=name;document.querySelector('#workspace-initial').textContent=name[0]||'W';document.querySelector('#breadcrumb-workspace').textContent=name}
  function roleSwitcher(){logout()}
  function workspaceSwitcher(){const options=authWorkspaces.map(w=>`<option value="${esc(w.id)}" ${w.id===currentWorkspace?'selected':''}>${esc(w.name)} · ${esc(w.role)}</option>`).join('');openDialog(`<div class="eyebrow">WORKSPACE</div><h2>Switch workspace</h2><div class="field"><label for="workspace-select">Workspace</label><select id="workspace-select">${options}</select></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="close-dialog">Cancel</button><button class="btn btn-primary" data-action="save-workspace">Switch workspace</button></div>`)}
  function canReviewClaim(){return ['Legal reviewer','Administrator'].includes(currentRole)}
  function canApproveContent(){return ['Brand manager','Administrator'].includes(currentRole)}
  function canClearFinding(f){if(['Unsupported claim','Unverified fact'].includes(f.kind))return canReviewClaim();if(f.kind==='Terminology')return ['Regional lead','Brand manager','Administrator'].includes(currentRole);return canApproveContent()}
  function needsReviewerClearance(f){return ['Unsupported claim','Unverified fact'].includes(f.kind)&&f.status!=='Reviewer cleared'}
  function save(){editCounter++;updatePending();const snapshot=JSON.stringify(state);apiQueue=apiQueue.then(async()=>{const response=await fetch('/api/state',{method:'PUT',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:snapshot,credentials:'same-origin'});const payload=await response.json();if(!response.ok){const error=new Error(payload.error||'Save failed');error.status=response.status;throw error}state=payload.state;updatePending();return true}).catch(async error=>{toast(error.message||'Could not save. Reload and sign in again.',true);await syncServer();if(error.status===409){const dialog=document.querySelector('#review-dialog');if(dialog.open)dialog.close()}return false});return apiQueue}
  function newId(prefix){return prefix+(globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID().replaceAll('-','').slice(0,16):Date.now().toString(36)+Math.random().toString(36).slice(2,8))}
  function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
  function updatePending(){document.querySelector('#nav-pending').textContent=state.reviews.filter(r=>r.status!=='Approved').length}
  function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;document.querySelector('#toast-region').append(el);setTimeout(()=>el.remove(),3000)}
  function setPage(page){currentPage=page;document.querySelectorAll('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.page===page));const name={dashboard:'Overview',reviews:'Reviews',knowledge:'Brand knowledge',insights:'Insights',team:'Team'}[page];document.querySelector('#crumb').textContent=name;if(location.hash!=='#'+page)history.replaceState(null,'','#'+page);render();if(page==='team'&&currentRole==='Administrator')loadTeam()}
  function heading(title,sub,button=''){const label=currentPage==='dashboard'?'TODAY · WORKSPACE':`${esc(authWorkspaces.find(w=>w.id===currentWorkspace)?.name||'WORKSPACE').toUpperCase()} · WORKSPACE`;return `<div class="page-heading"><div><div class="eyebrow">${label}</div><h1>${title}</h1><p>${sub}</p></div>${button}</div>`}
  function btnNew(){return '<button class="btn btn-primary" data-action="new-review"><span>＋</span> New review</button>'}
  function statusClass(s){return ({'Approved':'status-approved','In review':'status-review','Needs changes':'status-needs','Changes requested':'status-changes','Draft':'status-draft'})[s]||'status-draft'}
  function status(s){return `<span class="status-pill ${statusClass(s)}">${esc(s)}</span>`}
  function shortDate(d){return d.replace('Today · ','').replace('Yesterday · ','Yesterday').replace(' AM','').replace(' PM','')}
  function reviewRow(r,table=false){return `<div class="review-row" data-action="open-review" data-id="${r.id}"><div><div class="review-title">${esc(r.title)}</div><div class="review-meta">${esc(r.id)} <span>·</span> ${esc(r.type)} <span>·</span> ${r.findings.length} finding${r.findings.length===1?'':'s'}</div></div>${table?`<span class="row-owner">${esc(r.owner)}</span>`:''}<span class="row-date row-owner">${esc(shortDate(r.date))}</span>${status(r.status)}<span class="row-arrow">›</span></div>`}
  function renderDashboard(){const all=state.reviews, approved=all.filter(r=>r.status==='Approved').length, open=all.flatMap(r=>r.findings).filter(f=>f.status==='Open'||f.status==='Escalated'||needsReviewerClearance(f)).length;return `${heading('Good morning, '+esc(currentUser.name.split(' ')[0]),'Here’s what’s happening across your brand today.',btnNew())}<div class="stats-grid"><div class="card stat-card"><div class="stat-top">Awaiting review <span class="stat-icon">◷</span></div><div class="stat-value">${all.filter(r=>r.status!=='Approved').length}</div><div class="stat-foot"><span class="trend">${open} open findings</span></div></div><div class="card stat-card"><div class="stat-top">Approved reviews <span class="stat-icon">✓</span></div><div class="stat-value">${approved}</div><div class="stat-foot">Across ${all.length} submissions</div></div><div class="card stat-card"><div class="stat-top">Approval rate <span class="stat-icon">◎</span></div><div class="stat-value">${Math.round(100*approved/Math.max(1,all.length))}%</div><div class="stat-foot"><span class="trend">Of reviews in this workspace</span></div></div><div class="card stat-card"><div class="stat-top">Rules in your library <span class="stat-icon">◇</span></div><div class="stat-value">${state.rules.length}</div><div class="stat-foot">Approved workspace entries</div></div></div><div class="dashboard-grid"><section class="card panel"><div class="panel-head"><div><h2 class="section-title">Needs your attention</h2><div class="section-subtitle">Items waiting for a person to take the next step</div></div><a class="text-link" href="#reviews" data-page-link="reviews">View all reviews →</a></div><div class="review-list">${all.filter(r=>r.status!=='Approved').slice(0,4).map(r=>reviewRow(r)).join('')||'<div class="empty-state">You’re all caught up.</div>'}</div></section><section class="card panel trend-panel"><div class="panel-head"><div><h2 class="section-title">Review health</h2><div class="section-subtitle">Your workspace at a glance</div></div><span>↗</span></div><div class="trend-number">${approved}/${all.length}</div><div class="trend-caption">approved reviews in the current workspace</div><div class="coverage-head"><span>Unresolved reviews</span><b>${all.filter(r=>r.status!=='Approved').length}</b></div><div class="trend-foot">Clear findings before approval. Humans stay in control.</div></section></div><div class="bottom-grid"><section class="card panel"><div class="panel-head"><div><h2 class="section-title">Recent activity</h2><div class="section-subtitle">A transparent record of team decisions</div></div><a class="text-link" href="#insights" data-page-link="insights">View audit log →</a></div>${state.audit.slice(0,3).map(a=>`<div class="activity-item"><span class="activity-dot">${esc(a.icon||'•')}</span><div>${esc(a.text)}<small>${esc(a.time)}</small></div></div>`).join('')}</section><section class="card panel"><h2 class="section-title">Brand readiness</h2><div class="section-subtitle">Coverage from approved rules and facts</div><div class="coverage-head"><span>Knowledge entries</span><b>${state.rules.length}</b></div><div class="coverage-head"><span>Claim and fact sources</span><b>${state.rules.filter(r=>['Claims','Approved facts'].includes(r.category)).length}</b></div><p class="coverage-note">Keep source owners and review dates current. The workspace does not send expiry reminders.</p><a class="text-link" href="#knowledge" data-page-link="knowledge">Open knowledge base →</a></section></div>`}
  function renderReviews(){let list=state.reviews.filter(r=>activeFilter==='All reviews'||(activeFilter==='Needs attention'&&r.status!=='Approved')||r.status===activeFilter);return `${heading('Reviews','Track content from submission through a human decision.',btnNew())}<div class="toolbar"><label class="searchbox">⌕ <input id="review-search" placeholder="Search reviews by title or ID…"></label><select class="control" id="type-filter"><option>All content types</option>${['Email','Web page','Social post','Press release','Document','Other'].map(x=>`<option>${x}</option>`).join('')}</select><button class="btn btn-secondary btn-sm" data-action="export-audit">↓ Export log</button></div><div class="filter-tabs">${['All reviews','Needs attention','In review','Approved','Draft'].map(x=>`<button class="filter-tab ${activeFilter===x?'active':''}" data-filter="${x}">${x}</button>`).join('')}</div><div class="card review-table"><div class="review-table-head"><span>CONTENT</span><span>OWNER</span><span>UPDATED</span><span>STATUS</span><span></span></div><div id="review-list">${list.map(r=>reviewRow(r,true)).join('')||'<div class="empty-state"><strong>No reviews here yet</strong>Try another filter or submit a new piece of content.</div>'}</div></div>`}
  function renderKnowledge(){const rules=state.rules.filter(r=>activeKnowledge==='Guidelines'?['Tone of voice','Terminology','Accessibility'].includes(r.category):activeKnowledge==='Claims & facts'?['Claims','Approved facts'].includes(r.category):true);return `${heading('Brand knowledge','Your approved rules and facts are the evidence behind every review.',`<button class="btn btn-primary" data-action="add-rule">＋ Add rule or fact</button>`)}<div class="callout">✓ Confirm imported source text before it informs checks. Fact ownership, review-date reminders and asset rules are not managed in this workspace.</div><div class="knowledge-layout"><div class="card knowledge-nav">${['Guidelines','Claims & facts','Glossary','Assets','All sources'].map(x=>`<button class="knowledge-tab ${activeKnowledge===x?'active':''}" data-knowledge="${x}"><span>${({Guidelines:'◇','Claims & facts':'▤',Glossary:'Aa',Assets:'▧','All sources':'▦'})[x]}</span>${x}</button>`).join('')}</div><section class="card knowledge-content"><div class="panel-head"><div><h2 class="section-title">${activeKnowledge==='Guidelines'?'Approved guidelines':esc(activeKnowledge)}</h2><div class="section-subtitle">${rules.length} entries · Reviewed by ${esc(currentUser.name)}</div></div><div class="knowledge-tools"><input id="knowledge-search" placeholder="Search entries…"><button class="btn btn-secondary btn-sm" data-action="import-source">↑ Import source</button></div></div>${rules.map(r=>`<div class="rule-row"><div><b>${esc(r.title)}</b><p>${esc(r.detail)}</p><p>${esc(r.category)} · ${esc(r.source||('Confirmed by '+currentRole))} · Owner ${esc(r.owner||'Unassigned')} · Review ${esc(r.reviewDate||'Not scheduled')}</p></div><span class="rule-tag">${esc(r.status)}</span></div>`).join('')||'<div class="empty-state">No entries in this section yet.</div>'}<div class="audit-banner"><b>ⓘ</b><span>BrandSentinel only makes source-backed claims. If a fact has no approved source, a review marks it unverified for a person to decide.</span></div></section></div>`}
  function renderInsights(){const all=state.reviews, counts={};all.forEach(r=>r.findings.forEach(f=>counts[f.kind]=(counts[f.kind]||0)+1));const vals=Object.entries(counts).sort((a,b)=>b[1]-a[1]);const max=Math.max(1,...vals.map(x=>x[1]));const open=all.flatMap(r=>r.findings).filter(f=>f.status==='Open'||f.status==='Escalated'||needsReviewerClearance(f)).length;return `${heading('Insights','Understand where reviews slow down and where your guidelines need clarity.','<button class="btn btn-secondary" data-action="export-audit">↓ Export activity</button>')}<div class="stats-grid"><div class="card stat-card"><div class="stat-top">Total submissions <span class="stat-icon">▤</span></div><div class="stat-value">${all.length}</div><div class="stat-foot">In this workspace</div></div><div class="card stat-card"><div class="stat-top">Findings identified <span class="stat-icon">⌁</span></div><div class="stat-value">${all.reduce((n,r)=>n+r.findings.length,0)}</div><div class="stat-foot">Across ${new Set(all.flatMap(r=>r.findings.map(f=>f.kind))).size} check types</div></div><div class="card stat-card"><div class="stat-top">Still unresolved <span class="stat-icon">◷</span></div><div class="stat-value">${open}</div><div class="stat-foot">Human action is required</div></div><div class="card stat-card"><div class="stat-top">Approved <span class="stat-icon">✓</span></div><div class="stat-value">${all.filter(r=>r.status==='Approved').length}</div><div class="stat-foot">Publication remains in your channels</div></div></div><div class="insights-grid"><section class="card panel"><div class="panel-head"><div><h2 class="section-title">Findings by category</h2><div class="section-subtitle">Issues detected by checks in the current review set</div></div></div><div class="bar-chart">${vals.map(([k,v])=>`<div class="bar-set"><span class="bar-value">${v}</span><div class="bar" style="height:${Math.max(8,v/max*100)}%"></div><span class="bar-label">${esc(k)}</span></div>`).join('')||'<span class="section-subtitle">Submit content to see findings.</span>'}</div><div class="section-subtitle" style="margin-top:12px">Deterministic checks use the current workspace knowledge; no AI service is connected.</div></section><section class="card panel"><div class="panel-head"><div><h2 class="section-title">Decision activity</h2><div class="section-subtitle">Append-only in this workspace</div></div></div>${state.audit.map(a=>`<div class="audit-line"><span class="audit-icon">${esc(a.icon)}</span><span>${esc(a.text)}</span><span class="audit-time">${esc(a.time)}</span></div>`).join('')}<div class="audit-banner">For production use, audit records must be stored server-side with access controls and integrity protection.</div></section></div>`}
  function renderTeam(){if(currentRole!=='Administrator')return `${heading('Team','Only workspace administrators can manage access.')}`;const members=teamMembers.map(u=>`<div class="review-row"><div><div class="review-title">${esc(u.name)}</div><div class="review-meta">${esc(u.email)}</div></div><div class="form-grid"><select id="member-role-${u.id}" aria-label="Role for ${esc(u.name)}">${['Content creator','Brand manager','Legal reviewer','Regional lead','Administrator'].map(role=>`<option ${role===u.role?'selected':''}>${role}</option>`).join('')}</select><button class="btn btn-secondary btn-sm" data-action="update-member-role" data-user="${u.id}">Save role</button></div><span class="status-pill ${u.active?'status-approved':'status-needs'}">${u.active?'Active':'Disabled'}</span></div>`).join('')||'<div class="empty-state">No members found.</div>';return `${heading('Team','Manage workspace membership and roles.')}<section class="card panel"><div class="panel-head"><div><h2 class="section-title">Workspace members</h2><div class="section-subtitle">Role changes take effect on the next authenticated request.</div></div></div>${members}</section><section class="card panel" style="margin-top:18px"><h2 class="section-title">Add a member</h2><p class="section-subtitle">Share the initial password with the user through your approved secure channel.</p><div class="form-grid"><div class="field"><label for="member-name">Name</label><input id="member-name" maxlength="120"></div><div class="field"><label for="member-email">Email</label><input id="member-email" type="email" maxlength="254"></div></div><div class="form-grid"><div class="field"><label for="member-role">Workspace role</label><select id="member-role"><option>Content creator</option><option>Brand manager</option><option>Legal reviewer</option><option>Regional lead</option><option>Administrator</option></select></div><div class="field"><label for="member-password">Initial password (12+ characters)</label><input id="member-password" type="password" minlength="12" autocomplete="new-password"></div></div><button class="btn btn-primary" data-action="add-member">Add member</button></section><section class="card panel" style="margin-top:18px"><h2 class="section-title">Create a workspace</h2><div class="form-grid"><div class="field"><label for="workspace-name-new">Workspace name</label><input id="workspace-name-new" maxlength="120"></div><button class="btn btn-secondary" data-action="create-workspace">Create workspace</button></div></section>`}
  let teamMembers=[];
  async function loadTeam(){try{const response=await api('/api/users');const payload=await response.json();if(!response.ok)throw new Error(payload.error);teamMembers=payload.users;render()}catch(error){toast(error.message||'Could not load team members.',true)}}
  function render(){document.querySelector('#team-nav').hidden=currentRole!=='Administrator';const root=document.querySelector('#page-content');root.innerHTML=({dashboard:renderDashboard,reviews:renderReviews,knowledge:renderKnowledge,insights:renderInsights,team:renderTeam})[currentPage]();bindDynamic();updatePending()}
  function openDialog(html){document.querySelector('#dialog-content').innerHTML=html;const d=document.querySelector('#review-dialog');d.showModal();bindDynamic()}
  function newReview(){openDialog(`<div class="eyebrow">NEW SUBMISSION</div><h2>Start a content review</h2><p class="dialog-intro">Paste text or extract it from a supported document. Files are processed locally by the BrandSentinel server.</p><div class="form-grid"><div class="field"><label for="draft-title">Review title</label><input id="draft-title" required placeholder="e.g. November campaign email"></div><div class="field"><label for="draft-type">Content type</label><select id="draft-type"><option>Email</option><option>Web page</option><option>Social post</option><option>Press release</option><option>Document</option><option>Other</option></select></div></div><div class="field"><label for="draft-campaign">Campaign or project</label><input id="draft-campaign" placeholder="e.g. Fall launch"></div><div class="field"><label for="draft-file">Extract from file</label><div class="upload-zone"><input id="draft-file" type="file" accept=".txt,.md,.html,.htm,.pdf,.docx,.pptx"><button class="btn btn-secondary btn-sm" data-action="extract-review-file">Extract text</button><div class="field-hint">TXT, Markdown, HTML, PDF, Word or PowerPoint · 15 MB max</div></div></div><div class="field"><label for="draft-text">Content to review</label><textarea id="draft-text" required placeholder="Paste your content or extract text from a file…"></textarea><div class="field-hint">Checks: preferred terminology, unsupported guarantees, accessibility link text and tone cues.</div></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="close-dialog">Cancel</button><button class="btn btn-primary" data-action="submit-review">Run review →</button></div>`)}
  async function extractFile(file,targetId){if(!file){toast('Choose a file first.',true);return}try{let result,checks=[];if(location.protocol!=='file:'){const form=new FormData();form.append('file',file);const response=await api('/api/extract',{method:'POST',body:form});const payload=await response.json();if(!response.ok)throw new Error(payload.error||'File extraction failed');result=payload.text;checks=payload.checks||[]}else{const ext=file.name.split('.').pop().toLowerCase();if(!['txt','md','html','htm'].includes(ext))throw new Error('Run server.py to extract PDF, Word and PowerPoint files.');result=await file.text();if(['html','htm'].includes(ext))result=result.replace(/<(script|style)[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim()}const target=document.querySelector('#'+targetId);target.value=result;target.dataset.extractedFor=result;target.dataset.extractionChecks=JSON.stringify(checks);toast(`Extracted text from ${file.name}. Review it before submitting.`)}catch(error){toast(error.message||'Could not extract this file.',true)}}
  function addAudit(text,icon='✓'){state.audit.unshift({icon,text,time:'Just now',actor:currentUser.name,role:currentRole});state.audit=state.audit.slice(0,30)}
  function submitReview(){const title=document.querySelector('#draft-title').value.trim(),text=document.querySelector('#draft-text').value.trim();if(!title||!text){toast('Add a title and content before running the review.',true);return}const textArea=document.querySelector('#draft-text'),sourceChecks=textArea.dataset.extractedFor===text?JSON.parse(textArea.dataset.extractionChecks||'[]'):[];const r={id:newId('BS-').toUpperCase(),title,type:document.querySelector('#draft-type').value,campaign:document.querySelector('#draft-campaign').value||'Unassigned',owner:currentUser.name,date:'Today · '+new Intl.DateTimeFormat('en-US',{hour:'numeric',minute:'2-digit'}).format(new Date()),status:'Needs changes',text,sourceChecks,findings:BrandSentinelCore.runChecks(text,state.rules,sourceChecks)};if(!r.findings.length)r.status='In review';state.reviews.unshift(r);addAudit(`${currentUser.name} submitted “${title}”`,'↗');save();document.querySelector('#review-dialog').close();setPage('reviews');toast(`Review ${r.id} created. ${r.findings.length} finding${r.findings.length===1?'':'s'} to review.`);openReview(r.id)}
  function findingCard(f,r){return `<div class="finding-card"><div class="finding-top"><strong>${esc(f.kind)}</strong><span class="severity severity-${f.severity.toLowerCase()}">${esc(f.severity)}</span><span class="finding-state">${f.status==='Open'?'Needs your decision':f.status==='Escalated'||needsReviewerClearance(f)?'Awaiting authorised reviewer':esc(f.status)}</span></div><div class="finding-quote">“${esc(f.quote)}”</div><div class="finding-explainer">${esc(f.reason)}</div><div class="source-line"><span>↳</span><span><b>Source · ${esc(f.method)}</b><br>${esc(f.source)} <span>·</span> Exact rule match</span></div><div class="suggestion"><label>Suggested correction · You decide</label><span>${esc(f.suggestion)}</span></div>${f.status==='Open'?`<div class="finding-actions"><button class="btn btn-primary btn-sm" data-action="accept-finding" data-review="${r.id}" data-finding="${f.id}">✓ Accept suggestion</button><button class="btn btn-secondary btn-sm" data-action="edit-finding" data-review="${r.id}" data-finding="${f.id}">Edit</button><button class="btn btn-quiet btn-sm" data-action="dismiss-finding" data-review="${r.id}" data-finding="${f.id}">Dismiss</button><button class="btn btn-quiet btn-sm" data-action="escalate-finding" data-review="${r.id}" data-finding="${f.id}">Escalate</button></div>`:f.status==='Escalated'||needsReviewerClearance(f)?`<div class="finding-actions"><span class="resolve-note">Assigned to ${esc(f.assignedTo||'authorised reviewer')} · ${esc(f.note||f.creatorNote||'Human approval required')}</span><button class="btn btn-secondary btn-sm" data-action="clear-escalation" data-review="${r.id}" data-finding="${f.id}">Reviewer clear</button>${f.status==='Accepted'?`<button class="btn btn-quiet btn-sm" data-action="undo-finding" data-review="${r.id}" data-finding="${f.id}">Undo</button>`:''}</div>`:`<div class="finding-actions"><span class="resolve-note">${esc(f.status)} by ${esc(currentUser.name)}${f.note?` · ${esc(f.note)}`:''}</span>${f.status==='Accepted'?`<button class="btn btn-quiet btn-sm" data-action="undo-finding" data-review="${r.id}" data-finding="${f.id}">Undo</button>`:''}</div>`}</div>`}
  function reviewCollaboration(r){return `<section class="card panel" style="margin-top:14px"><div class="panel-head"><div><h3 class="section-title">Discussion and version history</h3><div class="section-subtitle">Comments, reviewer notes and saved content versions</div></div><button class="btn btn-secondary btn-sm" data-action="show-versions" data-id="${r.id}">↺ Version history</button></div>${(r.comments||[]).map(c=>`<div class="activity-item"><span class="activity-dot">${esc(c.author.slice(0,1))}</span><div><b>${esc(c.author)}</b> ${esc(c.text)}<small>${esc(c.createdAt)}</small></div></div>`).join('')||'<div class="section-subtitle" style="margin-bottom:10px">No comments yet. Add a reviewer note or mention a teammate with @name.</div>'}<div class="field"><label for="review-comment">Add a comment</label><textarea id="review-comment" style="min-height:70px" placeholder="Write a note or @mention a teammate…"></textarea></div><button class="btn btn-secondary btn-sm" data-action="add-comment" data-id="${r.id}">Add comment</button></section>`}
  async function showVersions(id){try{let versions=[];if(location.protocol!=='file:'){const response=await api(`/api/reviews/${encodeURIComponent(id)}/versions`);if(response.ok)versions=(await response.json()).versions||[]}if(!versions.length){const r=state.reviews.find(x=>x.id===id);versions=[{version:1,content:r?.text||'',content_hash:'workspace',created_at:r?.date||'Current session'}]}openDialog(`<div class="eyebrow">${esc(id)}</div><h2>Version history</h2><p class="dialog-intro">Each saved content change is retained for comparison. The newest version appears first.</p>${versions.map(v=>`<section class="card panel" style="margin-bottom:10px"><div class="panel-head"><b>Version ${v.version}</b><span class="section-subtitle">${esc(v.created_at)} · ${esc(v.content_hash).slice(0,12)}</span></div><div class="content-preview">${esc(v.content)}</div></section>`).join('')}<div class="dialog-actions"><button class="btn btn-secondary" data-action="back-review" data-id="${id}">Back to review</button></div>`)}catch{toast('Could not load version history.',true)}}
  function editDraft(id){const r=state.reviews.find(x=>x.id===id);if(!r||r.status==='Approved'){toast('Approved content is locked.',true);return}openDialog(`<div class="eyebrow">RESUBMIT CONTENT · ${esc(r.id)}</div><h2>Update your draft</h2><p class="dialog-intro">The changed draft is saved as a new version and checked against the current approved knowledge.</p><div class="field"><label for="resubmitted-text">Updated content</label><textarea id="resubmitted-text">${esc(r.text)}</textarea></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="back-review" data-id="${id}">Cancel</button><button class="btn btn-primary" data-action="save-resubmission" data-id="${id}">Save and recheck</button></div>`)}
  function openReview(id){const r=state.reviews.find(x=>x.id===id);if(!r)return;const open=r.findings.filter(f=>f.status==='Open'||f.status==='Escalated'||needsReviewerClearance(f)).length;const canApprove=BrandSentinelCore.canApprove(r.findings)&&r.status!=='Approved'&&canApproveContent(),approvalHint=canApproveContent()?'Resolve all findings first':'Brand manager approval required';openDialog(`<div class="eyebrow">${esc(r.id)} · ${esc(r.type)} · ${esc(r.campaign)}</div><h2>${esc(r.title)}</h2><p class="dialog-intro">Submitted by ${esc(r.owner)} · ${esc(r.date)} · Version ${1+(r.resubmissionCount||0)} · ${r.findings.length} finding${r.findings.length===1?'':'s'}</p><div class="split-review"><section><div class="panel-head"><div><h3 class="section-title">Submitted content</h3><div class="section-subtitle">Original draft is preserved</div></div><span>${status(r.status)}</span></div><div class="content-preview">${esc(r.text)}</div>${r.status!=='Approved'?`<button class="btn btn-secondary btn-sm" style="margin-top:10px" data-action="edit-draft" data-id="${r.id}">Edit draft and recheck</button>`:''}<div class="summary-box"><b>Review summary</b><br>${r.findings.length} checks flagged · ${open} unresolved · ${r.findings.filter(f=>(f.status==='Accepted'||f.creatorDecision==='Accepted')).length} accepted · ${r.findings.filter(f=>f.status==='Dismissed'||f.creatorDecision==='Dismissed').length} dismissed</div>${r.findings.some(f=>['Unsupported claim','Unverified fact'].includes(f.kind))?'<div class="audit-banner">Claims require a named human reviewer. BrandSentinel keeps approval under your control.</div>':''}</section><section><div class="panel-head"><div><h3 class="section-title">Explainable findings</h3><div class="section-subtitle">Resolve each item or leave it for review</div></div></div>${r.findings.map(f=>findingCard(f,r)).join('')||'<div class="empty-state"><strong>No findings</strong>Rule checks found no issues in the active workspace checks.</div>'}</section></div>${reviewCollaboration(r)}<div class="dialog-actions"><button class="btn btn-secondary" data-action="close-dialog">Close</button>${r.status!=='Approved'?`<button class="btn ${canApprove?'btn-primary':'btn-secondary'}" data-action="approve-review" data-id="${r.id}" ${canApprove?'':'disabled title="${approvalHint}"'}>✓ Approve version</button>`:`<span class="status-pill status-approved">✓ Approved version locked</span>`}</div><div class="audit-banner">AI use: No AI provider is connected; all checks are deterministic rules. · This demo does not publish content.</div>`)}
  function actFinding(action,rid,fid){const r=state.reviews.find(x=>x.id===rid),f=r?.findings.find(x=>x.id===fid);if(!f)return;if(action==='clear-escalation'&&!canClearFinding(f)){toast('This decision needs an authorised reviewer role.',true);return}const resolve=(status,note)=>{f.status=status;f.note=note||'';if(action==='accept-finding')r.text=r.text.replace(f.quote,f.suggestion);addAudit(`${currentUser.name} ${status.toLowerCase()} “${f.kind}” in ${r.title}`,status==='Escalated'?'↗':'✓');save();openReview(rid);toast(status==='Accepted'?'Suggestion accepted; a new draft version was saved.':status==='Dismissed'?'Finding dismissed with reason saved.':'Finding escalated to the authorised reviewer.')};
    if(action==='accept-finding'){resolve('Accepted');return}if(action==='undo-finding'){f.status='Open';f.note='';addAudit(`Alex Morgan reopened a ${f.kind} finding in ${r.title}`,'↺');save();openReview(rid);toast('Finding reopened.');return}
    const isEscalate=action==='escalate-finding',isClear=action==='clear-escalation';openDialog(`<div class="eyebrow">${isEscalate?'ESCALATE FINDING':isClear?'REVIEWER DECISION':'DISMISS FINDING'}</div><h2>${isEscalate?'Send to a human reviewer':isClear?'Clear this finding':'Record a dismissal reason'}</h2><p class="dialog-intro">${isEscalate?'The finding will stay unresolved until an authorised reviewer decides.':isClear?'An authorised reviewer records why the claim is acceptable. This decision is added to the audit log.':'A written reason is required so the team can learn from this decision.'}</p><div class="field"><label for="decision-note">${isEscalate?'Note for reviewer':isClear?'Reviewer rationale':'Reason'}</label><textarea id="decision-note" placeholder="${isEscalate?'Add context for the reviewer…':isClear?'Record the evidence and review decision…':'Explain why this finding does not apply…'}"></textarea></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="back-review" data-id="${rid}">Cancel</button><button class="btn ${isEscalate||isClear?'btn-primary':'btn-danger'}" data-action="save-decision" data-review="${rid}" data-finding="${fid}" data-mode="${isEscalate?'Escalated':isClear?'Reviewer cleared':'Dismissed'}">${isEscalate?'Escalate finding':isClear?'Clear as reviewer':'Save dismissal'}</button></div>`)}
  function editFinding(rid,fid){const r=state.reviews.find(x=>x.id===rid),f=r?.findings.find(x=>x.id===fid);if(!f)return;openDialog(`<div class="eyebrow">EDIT SUGGESTION</div><h2>Keep your intended meaning</h2><p class="dialog-intro">Edit the draft text, then save the version. This finding will be marked accepted by you.</p><div class="field"><label for="edited-text">Suggested correction</label><textarea id="edited-text">${esc(f.suggestion)}</textarea></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="back-review" data-id="${rid}">Cancel</button><button class="btn btn-primary" data-action="save-edit" data-review="${rid}" data-finding="${fid}">Save my edit</button></div>`)}
  function addRule(){openDialog(`<div class="eyebrow">BRAND KNOWLEDGE</div><h2>Add an approved rule or fact</h2><p class="dialog-intro">Only add content approved by your brand owner. Structured terminology entries are applied during review.</p><div class="field"><label for="rule-title">Rule or fact title</label><input id="rule-title" placeholder="e.g. Product name spelling"></div><div class="field"><label for="rule-category">Category</label><select id="rule-category"><option>Tone of voice</option><option>Terminology</option><option>Claims</option><option>Approved facts</option><option>Accessibility</option><option>Other</option></select></div><div class="form-grid"><div class="field"><label for="rule-avoid">Term to avoid · optional</label><input id="rule-avoid" placeholder="e.g. customers"></div><div class="field"><label for="rule-preferred">Preferred term · optional</label><input id="rule-preferred" placeholder="e.g. members"></div></div><div class="form-grid"><div class="field"><label for="rule-owner">Knowledge owner</label><input id="rule-owner" value="${esc(currentUser.name)}"></div><div class="field"><label for="rule-review-date">Review date</label><input id="rule-review-date" type="date"></div></div><div class="field"><label for="rule-detail">Approved guidance</label><textarea id="rule-detail" placeholder="Write the exact rule or source-backed fact…"></textarea></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="close-dialog">Cancel</button><button class="btn btn-primary" data-action="save-rule">Save approved entry</button></div>`)}
  function importSource(){openDialog(`<div class="eyebrow">KNOWLEDGE SOURCE IMPORT</div><h2>Import and confirm a source</h2><p class="dialog-intro">Extracted text becomes a proposed knowledge entry. Review and confirm it before checks use it.</p><div class="field"><label for="source-file">Source file</label><div class="upload-zone"><input id="source-file" type="file" accept=".txt,.md,.html,.htm,.pdf,.docx,.pptx"><button class="btn btn-secondary btn-sm" data-action="extract-source-file">Extract text</button><div class="field-hint">TXT, Markdown, HTML, PDF, Word or PowerPoint · 15 MB max</div></div></div><div class="form-grid"><div class="field"><label for="source-title">Entry title</label><input id="source-title" placeholder="Rule or fact title"></div><div class="field"><label for="source-category">Category</label><select id="source-category"><option>Tone of voice</option><option>Terminology</option><option>Claims</option><option>Approved facts</option><option>Accessibility</option><option>Other</option></select></div></div><div class="form-grid"><div class="field"><label for="source-owner">Knowledge owner</label><input id="source-owner" value="${esc(currentUser.name)}"></div><div class="field"><label for="source-review-date">Review date</label><input id="source-review-date" type="date"></div></div><div class="field"><label for="source-text">Extracted text · confirm before saving</label><textarea id="source-text" placeholder="Extracted source content appears here…"></textarea></div><div class="dialog-actions"><button class="btn btn-secondary" data-action="close-dialog">Cancel</button><button class="btn btn-primary" data-action="save-source">Confirm source entry</button></div>`)}
  async function exportLog(){let audit=state.audit;if(location.protocol!=='file:'){try{const response=await api('/api/audit');if(response.ok)audit=(await response.json()).entries.map(e=>e.details)}catch{}}const data={workspace:authWorkspaces.find(w=>w.id===currentWorkspace)?.name||'Workspace',exportedAt:new Date().toISOString(),reviews:state.reviews,audit};const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='brandsentinel-review-export.json';a.click();URL.revokeObjectURL(url);toast('Review activity exported as JSON.')}
  function bindDynamic(){document.querySelectorAll('[data-page-link]').forEach(a=>a.onclick=e=>{e.preventDefault();setPage(a.dataset.pageLink)});document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{activeFilter=b.dataset.filter;render()});document.querySelectorAll('[data-knowledge]').forEach(b=>b.onclick=()=>{activeKnowledge=b.dataset.knowledge;render()});document.querySelectorAll('[data-action]').forEach(el=>el.onclick=e=>{e.preventDefault();const a=el.dataset.action;switch(a){case'save-workspace':selectWorkspace(document.querySelector('#workspace-select').value);break;case'add-member':addMember();break;case'create-workspace':createWorkspace();break;case'update-member-role':updateMemberRole(el.dataset.user);break;case'new-review':newReview();break;case'close-dialog':document.querySelector('#review-dialog').close();break;case'submit-review':submitReview();break;case'edit-draft':editDraft(el.dataset.id);break;case'save-resubmission':{if(!['Content creator','Brand manager','Administrator'].includes(currentRole)){toast('This role cannot edit submitted content.',true);return}const r=state.reviews.find(x=>x.id===el.dataset.id),text=document.querySelector('#resubmitted-text').value.trim();if(!text){toast('Draft content cannot be empty.',true);return}if(text===r.text){toast('No changes to save.');return}r.text=text;r.resubmissionCount=(r.resubmissionCount||0)+1;r.findings=BrandSentinelCore.recheck(r.findings,text,state.rules,[]);r.sourceChecks=[];r.status=r.findings.some(f=>f.status==='Open'||f.status==='Escalated')?'Needs changes':'In review';addAudit(`${currentUser.name} resubmitted “${r.title}” as version ${r.resubmissionCount+1}`,'↗');save();openReview(r.id);toast('New version saved and rechecked against approved knowledge.');break}case'open-review':openReview(el.dataset.id);break;case'show-versions':showVersions(el.dataset.id);break;case'add-comment':{const r=state.reviews.find(x=>x.id===el.dataset.id),text=document.querySelector('#review-comment').value.trim();if(!text){toast('Write a comment before adding it.',true);return}r.comments=r.comments||[];r.comments.push({author:currentUser.name,text,createdAt:'Just now'});addAudit(currentUser.name+' commented on '+r.title,'◌');save();openReview(r.id);toast('Comment added to the review.');break}case'accept-finding':case'dismiss-finding':case'escalate-finding':case'clear-escalation':case'undo-finding':actFinding(a,el.dataset.review,el.dataset.finding);break;case'edit-finding':editFinding(el.dataset.review,el.dataset.finding);break;case'back-review':openReview(el.dataset.id);break;case'save-decision':{const note=document.querySelector('#decision-note').value.trim();if(!note){toast('Please add a written reason or reviewer note.',true);return}const r=state.reviews.find(x=>x.id===el.dataset.review),f=r.findings.find(x=>x.id===el.dataset.finding);if(el.dataset.mode==='Reviewer cleared'&&needsReviewerClearance(f)&&['Accepted','Dismissed'].includes(f.status)){f.creatorDecision=f.status;f.creatorNote=f.note}f.status=el.dataset.mode;f.note=note;if(['Accepted','Dismissed'].includes(f.status)&&['Unsupported claim','Unverified fact'].includes(f.kind))f.assignedTo='Priya Shah';if(el.dataset.mode==='Escalated')f.assignedTo=['Unsupported claim','Unverified fact'].includes(f.kind)?'Priya Shah':f.kind==='Terminology'?'Jordan Lee':'Alex Morgan';const actor=el.dataset.mode==='Reviewer cleared'?'Authorised reviewer':currentUser.name;addAudit(`${actor} ${el.dataset.mode.toLowerCase()} “${f.kind}” in ${r.title}`,el.dataset.mode==='Escalated'?'↗':'✓');save();openReview(r.id);toast(el.dataset.mode==='Dismissed'?'Dismissal reason saved.':el.dataset.mode==='Reviewer cleared'?'Reviewer decision saved; finding cleared.':'Finding escalated to the authorised reviewer.');break}case'save-edit':{const r=state.reviews.find(x=>x.id===el.dataset.review),f=r.findings.find(x=>x.id===el.dataset.finding),edited=document.querySelector('#edited-text').value.trim();if(!edited){toast('The correction cannot be empty.',true);return}r.text=r.text.replace(f.quote,edited);f.status='Accepted';f.note='Edited by '+currentUser.name;if(['Unsupported claim','Unverified fact'].includes(f.kind))f.assignedTo='Priya Shah';addAudit(`${currentUser.name} edited and accepted a ${f.kind} suggestion in ${r.title}`);save();openReview(r.id);toast('Your edit was saved as a new draft version.');break}case'approve-review':{if(!canApproveContent()){toast('Only a brand manager or administrator can approve this content.',true);return}const r=state.reviews.find(x=>x.id===el.dataset.id);if(!BrandSentinelCore.canApprove(r.findings)){toast('Resolve all open and escalated findings before approval.',true);return}r.status='Approved';r.approvedAt=new Date().toISOString();addAudit(`${currentUser.name} approved “${r.title}”`);save();openReview(r.id);toast('Approved version locked. Ready for your publishing channel.');break}case'add-rule':addRule();break;case'save-rule':{if(!canApproveContent()){toast('Only a brand manager or administrator can change approved knowledge.',true);return}const title=document.querySelector('#rule-title').value.trim(),detail=document.querySelector('#rule-detail').value.trim();if(!title||!detail){toast('Add a title and approved guidance.',true);return}state.rules.push({id:newId('r'),title,detail,category:document.querySelector('#rule-category').value,bannedTerm:document.querySelector('#rule-avoid').value.trim(),preferredTerm:document.querySelector('#rule-preferred').value.trim(),owner:document.querySelector('#rule-owner').value.trim()||currentUser.name,reviewDate:document.querySelector('#rule-review-date').value||'',status:'Active'});addAudit(`${currentUser.name} added “${title}” to brand knowledge`,'◇');save();document.querySelector('#review-dialog').close();render();toast('Approved entry added to the knowledge base.');break}case'export-audit':exportLog();break;case'import-source':importSource();break;case'extract-review-file':extractFile(document.querySelector('#draft-file').files[0],'draft-text');break;case'extract-source-file':extractFile(document.querySelector('#source-file').files[0],'source-text');break;case'save-source':{if(!canApproveContent()){toast('Only a brand manager or administrator can confirm a source.',true);return}const title=document.querySelector('#source-title').value.trim(),detail=document.querySelector('#source-text').value.trim();if(!title||!detail){toast('Add a title and confirm the extracted source text.',true);return}state.rules.push({id:newId('r'),title,detail,category:document.querySelector('#source-category').value,owner:document.querySelector('#source-owner').value.trim()||currentUser.name,reviewDate:document.querySelector('#source-review-date').value||'',status:'Active',source:document.querySelector('#source-file').files[0]?.name||'Confirmed source'});addAudit(currentUser.name+' confirmed source entry: '+title,'◇');save();document.querySelector('#review-dialog').close();render();toast('Confirmed source added to brand knowledge.');break}}});
    const search=document.querySelector('#review-search');if(search)search.oninput=()=>{const q=search.value.toLowerCase(),type=document.querySelector('#type-filter').value;const items=state.reviews.filter(r=>(activeFilter==='All reviews'||(activeFilter==='Needs attention'&&r.status!=='Approved')||r.status===activeFilter)&&(!q||r.title.toLowerCase().includes(q)||r.id.toLowerCase().includes(q))&&(type==='All content types'||r.type===type));document.querySelector('#review-list').innerHTML=items.map(r=>reviewRow(r,true)).join('')||'<div class="empty-state">No matching reviews.</div>';bindDynamic()};const type=document.querySelector('#type-filter');if(type)type.onchange=()=>{const ev=new Event('input');document.querySelector('#review-search').dispatchEvent(ev)};const ks=document.querySelector('#knowledge-search');if(ks)ks.oninput=()=>{const q=ks.value.toLowerCase();document.querySelectorAll('.rule-row').forEach(row=>row.classList.toggle('hidden',!row.textContent.toLowerCase().includes(q)))}}
  async function addMember(){const body={name:document.querySelector('#member-name').value.trim(),email:document.querySelector('#member-email').value.trim(),role:document.querySelector('#member-role').value,password:document.querySelector('#member-password').value};try{const response=await api('/api/users',{method:'POST',body:JSON.stringify(body)}),payload=await response.json();if(!response.ok)throw new Error(payload.error);toast('Member added. Share the initial password securely.');await syncServer()}catch(error){toast(error.message||'Could not add member.',true)}}
  async function updateMemberRole(userId){const role=document.querySelector('#member-role-'+userId).value;try{const response=await api('/api/users/'+encodeURIComponent(userId),{method:'PUT',body:JSON.stringify({role})}),payload=await response.json();if(!response.ok)throw new Error(payload.error);toast('Workspace role updated.');const current=await api('/api/auth/me');if(current.ok)setAuthenticated(await current.json());await syncServer()}catch(error){toast(error.message||'Could not update role.',true)}}
  async function createWorkspace(){const name=document.querySelector('#workspace-name-new').value.trim();try{const response=await api('/api/workspaces',{method:'POST',body:JSON.stringify({name})}),payload=await response.json();if(!response.ok)throw new Error(payload.error);authWorkspaces=payload.workspaces;updateWorkspaceUI();toast('Workspace created. Switch to it from the workspace menu.')}catch(error){toast(error.message||'Could not create workspace.',true)}}
  async function api(path,options={}){const headers=new Headers(options.headers||{});if(options.body&&!(options.body instanceof FormData)&&!headers.has('Content-Type'))headers.set('Content-Type','application/json');if(options.method&&options.method!=='GET'&&path!=='/api/auth/login')headers.set('X-CSRF-Token',csrfToken);return fetch(path,{...options,headers,credentials:'same-origin'})}
  function setAuthenticated(me){csrfToken=me.csrfToken;currentUser={...me.user,initials:(me.user.name||'BS').split(/\s+/).map(x=>x[0]).join('').slice(0,2).toUpperCase()};currentRole=me.role;currentWorkspace=me.workspace.id;authWorkspaces=me.workspaces||[];updateCurrentUser();updateWorkspaceUI();document.querySelector('#auth-screen').hidden=true;document.querySelector('#app-shell').hidden=false}
  async function syncServer(){try{const response=await api('/api/state');if(response.status===401){showLogin();return}if(!response.ok)throw new Error('Could not load workspace');state=await response.json();updatePending();setPage(currentPage)}catch(error){toast(error.message||'Could not load workspace.',true)}}
  async function selectWorkspace(workspace){if(!workspace||workspace===currentWorkspace){document.querySelector('#review-dialog').close();return}try{const response=await api('/api/workspaces/switch',{method:'POST',body:JSON.stringify({workspaceId:workspace})}),payload=await response.json();if(!response.ok)throw new Error(payload.error);csrfToken=payload.csrfToken;currentWorkspace=payload.workspace.id;currentRole=payload.role;authWorkspaces=payload.workspaces;updateCurrentUser();updateWorkspaceUI();document.querySelector('#review-dialog').close();await syncServer()}catch(error){toast(error.message||'Workspace switch failed.',true)}}
  function showLogin(message=''){document.querySelector('#app-shell').hidden=true;document.querySelector('#auth-screen').hidden=false;document.querySelector('#auth-message').textContent=message}
  async function boot(){const requested=location.hash.slice(1);if(['dashboard','reviews','knowledge','insights','team'].includes(requested))currentPage=requested;const status=await api('/api/auth/status');const setup=status.ok?(await status.json()).setupRequired:false;document.querySelector('#setup-help').hidden=!setup;document.querySelector('#login-submit').disabled=setup;if(setup)document.querySelector('#auth-message').textContent='No administrator is configured yet.';const me=await api('/api/auth/me');if(me.ok){const payload=await me.json();setAuthenticated(payload);await syncServer()}else showLogin(setup?'':'Sign in to continue.')}
  async function logout(){try{await api('/api/auth/logout',{method:'POST',body:'{}'})}catch{}csrfToken='';state={rules:[],reviews:[],audit:[]};showLogin('You have been signed out.')}
  document.querySelector('#login-form').addEventListener('submit',async event=>{event.preventDefault();const button=document.querySelector('#login-submit'),message=document.querySelector('#auth-message');button.disabled=true;message.textContent='Signing in…';try{const response=await api('/api/auth/login',{method:'POST',body:JSON.stringify({email:document.querySelector('#login-email').value,password:document.querySelector('#login-password').value})}),payload=await response.json();if(!response.ok)throw new Error(payload.error||'Sign in failed');setAuthenticated(payload);await syncServer()}catch(error){message.textContent=error.message||'Sign in failed.'}finally{button.disabled=false}});
  document.querySelectorAll('.nav-link').forEach(a=>a.onclick=e=>{e.preventDefault();setPage(a.dataset.page)});document.querySelector('#review-dialog').addEventListener('click',e=>{if(e.target===e.currentTarget)e.currentTarget.close()});document.querySelector('#help-button').onclick=()=>toast('Use the left navigation to explore reviews, knowledge and insights.');document.querySelector('#profile-menu').onclick=roleSwitcher;document.querySelector('#workspace-menu').onclick=workspaceSwitcher;document.querySelector('#account-menu').onclick=roleSwitcher;window.addEventListener('hashchange',()=>{const page=location.hash.slice(1);if(['dashboard','reviews','knowledge','insights','team'].includes(page))setPage(page)});boot().catch(()=>showLogin('The service is unavailable. Start the BrandSentinel server and reload.'));
})();
